package com.example;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Base64;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

public class ImagSupport {
public static void main(String[] args) throws IOException {
	String jsonResponse="{\r\n"
			+ "    \"created\": 1780566631,\r\n"
			+ "    \"background\": \"opaque\",\r\n"
			+ "    \"data\": [\r\n"
			+ "        {\r\n"
			+ "            \"b64_json\": \"\"\r\n"
			+ "        }\r\n"
			+ "    ],\r\n"
			+ "    \"output_format\": \"png\",\r\n"
			+ "    \"quality\": \"medium\",\r\n"
			+ "    \"size\": \"1024x1024\",\r\n"
			+ "    \"usage\": {\r\n"
			+ "        \"input_tokens\": 227,\r\n"
			+ "        \"input_tokens_details\": {\r\n"
			+ "            \"image_tokens\": 194,\r\n"
			+ "            \"text_tokens\": 33\r\n"
			+ "        },\r\n"
			+ "        \"output_tokens\": 1056,\r\n"
			+ "        \"output_tokens_details\": {\r\n"
			+ "            \"image_tokens\": 1056,\r\n"
			+ "            \"text_tokens\": 0\r\n"
			+ "        },\r\n"
			+ "        \"total_tokens\": 1283\r\n"
			+ "    }\r\n"
			+ "}";
	JsonNode root =
	        new ObjectMapper().readTree(jsonResponse);

	String b64 =
	        root.path("data")
	            .get(0)
	            .path("b64_json")
	            .asText();

	byte[] imageBytes =
	        Base64.getDecoder().decode(b64);

	Files.write(
	        Path.of("D:/Albin/k_teaching.png"),
	        imageBytes);
	System.out.println("Done...");
	}
}
